// ---- host logic: examples/api_tours/style_class/host.cpp ----
// API tour (C++ Wrapper): classes, inline style, computed style, stylesheets and animation state.
// Same page, checks and case as examples/c/ports/kui_api_style_class.c (and the Go / Rust ports):
// on start the host calls every method once, checks the result and logs one row per check into
// #tour-log. Animation state is only observable once frames run, so those checks finish from a
// 400 ms timer and #tour-result becomes "PASS n/n" then. The panel buttons repeat the calls.
//
// Wrapper differences from the C port (no gaps in this tour):
//   * CSSStyleDeclaration::getPropertyValue reads a missing property (KUI_ERR_NOT_FOUND) as an
//     empty string, so the "missing" checks compare against "" instead of the status.
//   * kui_element_get_animation_state / kui_document_get_animation_counts are reached through
//     Document::animationManager() / transitionManager() (one flag / count per method).

#include <functional>
#include <sstream>
#include <vector>

namespace {

kui::Document* g_doc = nullptr;

// ---- Self-check bookkeeping: count, log one <tr> per check, publish the verdict ----------
// check(): a documented behaviour; a failure makes the tour FAIL. (No known engine bugs in this
// tour; see examples/api_tours/dom_tree/host.cpp for the known() variant.)

int g_total = 0;
int g_failed = 0;
std::string g_failed_names;

template <typename... Parts>
std::string cat(const Parts&... parts) {
    std::ostringstream out;
    (out << ... << parts);
    return out.str();
}

void log_row(const std::string& name, const std::string& result, const std::string& cell) {
    kui::Element* log = g_doc->getElementById("tour-log");
    if (!log) return;
    auto row = g_doc->createElement("tr");
    row->setAttribute("data-check", name);
    row->setAttribute("data-result", result);
    if (result != "ok") row->addClass("bad");
    auto first = g_doc->createElement("td");
    first->setTextContent(name);
    row->appendChild(first);
    auto second = g_doc->createElement("td");
    second->setTextContent(cell);
    row->appendChild(second);
    log->appendChild(row);
}

void check(const std::string& name, bool ok, const std::string& detail) {
    g_total++;
    if (ok) {
        log_row(name, "ok", "ok");
        return;
    }
    g_failed++;
    g_failed_names += (g_failed_names.empty() ? "" : ", ") + name;
    std::fprintf(stderr, "tour check failed: %s: %s\n", name.c_str(), detail.c_str());
    log_row(name, "fail", "FAIL: " + detail);
}

void finish() {
    kui::Element* result = g_doc->getElementById("tour-result");
    if (!result) return;
    std::string text = g_failed == 0 ? cat("PASS ", g_total, "/", g_total)
                                     : cat("FAIL ", g_failed, "/", g_total, ": ", g_failed_names);
    result->setTextContent(text);
    result->setAttribute("data-total", std::to_string(g_total));
    result->setAttribute("data-failed", std::to_string(g_failed));
    result->addClass(g_failed == 0 ? "pass" : "fail");
}

// A Wrapper method that throws (kui::Error) fails its group instead of aborting the tour.
void run_group(const char* group, const std::function<void()>& body) {
    try {
        body();
    } catch (const std::exception& error) {
        check(cat(group, ".exception"), false, error.what());
    }
}

// ---- Small readers ---------------------------------------------------------------------------

std::string class_of(const kui::Element* element) { return element ? element->className() : std::string(); }
bool contains(const kui::Element* element, const char* token) { return element && element->hasClass(token); }
std::string inline_value(const kui::Element* element, const char* property) {
    return element ? element->style()->getPropertyValue(property) : std::string();
}
unsigned property_count(const kui::Element* element) { return element ? element->style()->length() : 0u; }
std::string style_text_of(const kui::Element* element) {
    return element ? element->style()->cssText() : std::string();
}
std::string computed(kui::Element* element, const char* property) {
    return element ? element->computedStylePropertyValue(property) : std::string();
}
std::string computed_by_id(const char* id, const char* property) {
    return computed(g_doc->getElementById(id), property);
}
bool has(const std::string& text, const char* part) { return text.find(part) != std::string::npos; }

void set_text(const char* id, const std::string& text) {
    if (kui::Element* element = g_doc->getElementById(id)) element->setTextContent(text);
}

// "n: name=value[ !important], ..." for every inline property.
std::string describe_inline(const kui::Element* element) {
    const unsigned count = property_count(element);
    std::string out = cat(count, ":");
    for (unsigned index = 0; index < count; ++index) {
        const std::string name = element->style()->item(index);
        out += cat(index ? "," : "", " ", name, "=", inline_value(element, name.c_str()),
                   element->style()->isImportant(name) ? " !important" : "");
    }
    return out;
}

// The page's own <style> text, read from <head>; empty when absent.
std::string page_css() {
    kui::Element* head = g_doc->head();
    kui::Element* style = head ? head->querySelector("style") : nullptr;
    return style ? style->textContent() : std::string();
}

// ---- Class list: add / remove / toggle / contains, class name and id -------------------------

void check_class_list() {
    kui::Element* el = g_doc->getElementById("sc-cls");
    std::string text = el ? el->id() : std::string();
    check("el.get_id", text == "sc-cls", cat("id '", text, "'"));
    text = class_of(el);
    check("el.get_class_name", text == "a b", cat("className '", text, "'"));
    if (!el) return;

    el->addClass("c");
    text = class_of(el);
    check("el.class_list_add", text == "a b c" && contains(el, "c"), cat("className '", text, "'"));
    el->addClass("a");
    text = class_of(el);
    check("el.class_list_add-duplicate", text == "a b c", cat("className '", text, "'"));

    el->removeClass("b");
    text = class_of(el);
    check("el.class_list_remove", text == "a c" && !contains(el, "b"),
          cat("className '", text, "', contains(b) ", contains(el, "b")));
    check("el.class_list_contains", contains(el, "a") && !contains(el, "zz"),
          cat("contains(a) ", contains(el, "a"), ", contains(zz) ", contains(el, "zz")));

    el->toggleClass("d");
    const bool on = contains(el, "d");
    el->toggleClass("d");
    const bool off = contains(el, "d");
    check("el.class_list_toggle", on && !off, cat("after toggles ", on, " then ", off));

    el->setClassName("tour-wide");
    text = class_of(el);
    check("el.set_class_name", text == "tour-wide" && !contains(el, "a"), cat("className '", text, "'"));
    // The page stylesheet gives #sc-cls.tour-wide a width of 77px.
    text = computed(el, "width");
    check("el.class_drives_style", text == "77px", cat("computed width '", text, "'"));
}

// ---- Inline style: properties, !important, enumeration, whole-declaration text -------------

void check_inline_style() {
    kui::Element* el = g_doc->getElementById("sc-style");
    if (!el) {
        check("el.style-fixture", false, "#sc-style missing");
        return;
    }
    kui::CSSStyleDeclaration* style = el->style();

    std::string value = style->getPropertyValue("color");
    check("el.get_style_property-missing", value.empty(), cat("color '", value, "'"));

    // kui_c.h: named colours come back serialized as hex, lengths keep their unit.
    style->setProperty("color", "red");
    value = style->getPropertyValue("color");
    check("el.set_get_style_property", value == "#ff0000", cat("color '", value, "'"));
    style->setProperty("width", "100px");
    value = style->getPropertyValue("width");
    check("el.get_style_property-length", value == "100px", cat("width '", value, "'"));

    const bool important = style->isImportant("color");
    style->setProperty("background-color", "#00ff00", true);
    const bool after = style->isImportant("background-color");
    check("el.style_property_is_important", !important && after,
          cat("color ", important, ", background-color ", after));

    const unsigned count = style->length();
    std::string names;
    for (unsigned index = 0; index < count; ++index) names += (index ? "," : "") + style->item(index);
    check("el.get_style_property_count_name",
          count == 3 && has(names, "color") && has(names, "width") && has(names, "background-color"),
          cat("count ", count, ", names '", names, "'"));

    value = style->cssText();
    check("el.get_style_text", has(value, "width") && has(value, "100px") && has(value, "background-color") &&
          has(value, "!important"), cat("cssText '", value, "'"));

    // setCssText replaces the whole declaration.
    style->setCssText("margin-left: 4px; padding-top: 2px");
    value = style->getPropertyValue("margin-left");
    std::string color = style->getPropertyValue("color");
    check("el.set_style_text", style->length() == 2 && value == "4px" && color.empty(),
          cat("count ", style->length(), ", margin-left '", value, "', color '", color, "'"));

    style->removeProperty("margin-left");
    value = style->getPropertyValue("margin-left");
    check("el.remove_style_property", value.empty() && style->length() == 1,
          cat("margin-left '", value, "', count ", style->length()));
}

// ---- Computed style: the cascade's resolved values ----------------------------------------

void check_computed() {
    kui::Element* el = g_doc->getElementById("cs-target");
    const std::string display = computed(el, "display");
    const std::string width = computed(el, "width");
    const std::string font = computed(el, "font-size");
    std::string padding = computed(el, "padding-left");
    check("el.get_computed_style_value", display == "flex" && width == "240px" && font == "15px" &&
          padding == "8px", cat("display '", display, "', width '", width, "', font-size '", font,
                                "', padding-left '", padding, "'"));
    // An unknown property succeeds with an empty value (the Wrapper throws on any other error).
    const std::string unknown = computed(el, "no-such-property");
    check("el.get_computed_style_value-unknown", el && unknown.empty(), cat("value '", unknown, "'"));

    // Inline style feeds the cascade too.
    padding = computed_by_id("sc-style", "padding-top");
    check("el.get_computed_style_value-inline", padding == "2px", cat("padding-top '", padding, "'"));
}

// ---- Stylesheets & profile: add, clear every author sheet, restore the page's own -----------

void check_stylesheets() {
    const kui::Document::StyleProfile profile = g_doc->styleProfile();
    check("doc.get_style_profile", profile == kui::Document::StyleProfile::NativeGui,
          cat("profile ", static_cast<int>(profile)));

    // C++-only check: switch to BrowserCompat, read back, and restore the original profile right
    // away in the same call (no frame in between), so the later checks see the page unchanged.
    g_doc->setStyleProfile(kui::Document::StyleProfile::BrowserCompat);
    const kui::Document::StyleProfile switched = g_doc->styleProfile();
    g_doc->setStyleProfile(profile);
    const kui::Document::StyleProfile restored = g_doc->styleProfile();
    check("doc.set_style_profile",
          switched == kui::Document::StyleProfile::BrowserCompat && restored == profile,
          cat("switched ", static_cast<int>(switched), ", restored ", static_cast<int>(restored)));

    const std::string css = page_css();
    g_doc->addStylesheet("#sc-sheet { width: 123px; }");
    std::string width = computed_by_id("sc-sheet", "width");
    check("doc.add_stylesheet", width == "123px", cat("width '", width, "'"));

    check("head.page_css", has(css, "#cs-target"),
          cat("page <style> text ", css.empty() ? "missing" : "lacks #cs-target"));

    // Clearing drops the page sheet as well as ours: #cs-target falls back to display:block.
    g_doc->clearStylesheets();
    std::string display = computed_by_id("cs-target", "display");
    width = computed_by_id("sc-sheet", "width");
    check("doc.clear_stylesheets", display == "block" && width != "123px",
          cat("display '", display, "', width '", width, "'"));

    if (!css.empty()) g_doc->addStylesheet(css);
    display = computed_by_id("cs-target", "display");
    width = computed_by_id("sc-sheet", "width");
    check("doc.add_stylesheet-restore", !css.empty() && display == "flex" && width != "123px",
          cat("css ", css.size(), " bytes, display '", display, "', width '", width, "'"));
}

// ---- Animation state: needs running frames, so it is checked from a timer -----------------

void check_animation() {
    kui::AnimationManager* animations = g_doc->animationManager();
    kui::TransitionManager* transitions = g_doc->transitionManager();
    kui::Element* box = g_doc->getElementById("anim-box");
    kui::Element* bar = g_doc->getElementById("sc-trans");
    kui::Element* idle = g_doc->getElementById("cls-target");

    bool animating = animations->hasActiveAnimations(box);
    bool transitioning = transitions->hasActiveTransitions(box);
    check("el.get_animation_state-animation", box && animating,
          cat("animating ", animating, ", transitioning ", transitioning));
    animating = animations->hasActiveAnimations(bar);
    transitioning = transitions->hasActiveTransitions(bar);
    check("el.get_animation_state-transition", bar && transitioning,
          cat("animating ", animating, ", transitioning ", transitioning));
    animating = animations->hasActiveAnimations(idle);
    transitioning = transitions->hasActiveTransitions(idle);
    check("el.get_animation_state-idle", idle && !animating && !transitioning,
          cat("animating ", animating, ", transitioning ", transitioning));
    const kui::u32 running = animations->activeAnimationCount();
    const kui::u32 moving = transitions->activeTransitionCount();
    check("doc.get_animation_counts", running >= 1 && moving >= 1,
          cat("animations ", running, ", transitions ", moving));
}

// Starts the #anim-box animation (class .spinning) and a 2 s width transition on #sc-trans
// (inline style beats the 40px sheet value). Runs after the stylesheet checks only so that those
// checks see a quiet page; clearing the sheet that holds a running animation's @keyframes is safe
// (the engine cancels that animation: test_keyframes_stylesheet_removal).
void start_animation_checks() {
    if (kui::Element* box = g_doc->getElementById("anim-box")) box->addClass("spinning");
    computed_by_id("sc-trans", "width");  // settle the old value first
    if (kui::Element* bar = g_doc->getElementById("sc-trans")) bar->style()->setProperty("width", "200px");
    try {
        kui::Platform::setTimeout([] {
            run_group("animation", check_animation);
            finish();
        }, 400);
    } catch (const std::exception& error) {
        check("animation.timer", false, cat("Platform::setTimeout failed: ", error.what()));
        finish();
    }
}

// ---- Panel buttons -----------------------------------------------------------------------

void show_classes() {
    kui::Element* el = g_doc->getElementById("cls-target");
    set_text("cls-out", cat("#", el ? el->id() : std::string(), " class=\"", class_of(el), "\" | accent=",
                            contains(el, "accent") ? "yes" : "no"));
}

void on_cls_toggle() {
    if (kui::Element* el = g_doc->getElementById("cls-target")) el->toggleClass("accent");
    show_classes();
}

void on_cls_add() {
    if (kui::Element* el = g_doc->getElementById("cls-target")) el->addClass("big");
    show_classes();
}

void on_cls_remove() {
    if (kui::Element* el = g_doc->getElementById("cls-target")) el->removeClass("big");
    show_classes();
}

void on_cls_reset() {
    if (kui::Element* el = g_doc->getElementById("cls-target")) el->setClassName("card");
    show_classes();
}

void show_style_text() {
    const std::string text = style_text_of(g_doc->getElementById("st-target"));
    set_text("st-out", text.empty() ? std::string("(no inline style)") : text);
}

void on_st_set() {
    if (kui::Element* el = g_doc->getElementById("st-target")) {
        el->style()->setProperty("color", "#b91c1c");
        el->style()->setProperty("background-color", "#fee2e2", true);
    }
    show_style_text();
}

void on_st_text() {
    if (kui::Element* el = g_doc->getElementById("st-target"))
        el->style()->setCssText("background-color: #fef3c7; padding: 12px");
    show_style_text();
}

void on_st_remove() {
    if (kui::Element* el = g_doc->getElementById("st-target")) el->style()->removeProperty("background-color");
    show_style_text();
}

void on_st_list() { set_text("st-out", describe_inline(g_doc->getElementById("st-target"))); }

void on_cs_read() {
    kui::Element* el = g_doc->getElementById("cs-target");
    set_text("cs-out", cat("display=", computed(el, "display"), " | width=", computed(el, "width"),
                           " | font-size=", computed(el, "font-size"), " | color=", computed(el, "color")));
}

void on_cs_wide() {
    if (kui::Element* el = g_doc->getElementById("cs-target")) el->toggleClass("wide");
    on_cs_read();
}

void on_sheet_add() {
    g_doc->addStylesheet("#sheet-probe { background-color: #dcfce7; border-left-color: #16a34a; }");
    set_text("sheet-out", "host sheet added");
}

// Safe while #anim-box is animating: the animation whose @keyframes live in a cleared sheet is
// cancelled, and the restored page sheet starts it again.
void on_sheet_clear() {
    const std::string css = page_css();
    g_doc->clearStylesheets();
    if (!css.empty()) g_doc->addStylesheet(css);
    set_text("sheet-out", !css.empty() ? "cleared all sheets, page sheet restored"
                                       : "cleared all sheets (page <style> not found)");
}

void on_sheet_profile() {
    set_text("sheet-out", g_doc->styleProfile() == kui::Document::StyleProfile::BrowserCompat
                              ? "style profile = browser-compat"
                              : "style profile = native-gui");
}

void on_anim_toggle() {
    if (kui::Element* el = g_doc->getElementById("anim-box")) el->toggleClass("spinning");
}

void on_trans_go() {
    if (kui::Element* el = g_doc->getElementById("trans-box")) el->toggleClass("wide");
}

void on_anim_read() {
    const bool animating = g_doc->animationManager()->hasActiveAnimations(g_doc->getElementById("anim-box"));
    const bool transitioning =
        g_doc->transitionManager()->hasActiveTransitions(g_doc->getElementById("trans-box"));
    set_text("anim-out", cat("box: animating=", animating ? "yes" : "no", " | bar: transitioning=",
                             transitioning ? "yes" : "no", " | doc: animations=",
                             g_doc->animationManager()->activeAnimationCount(), " transitions=",
                             g_doc->transitionManager()->activeTransitionCount()));
}

// Clicks on #id run `handler` (a missing button is reported as a failed check).
void on_click(const char* id, void (*handler)()) {
    kui::Element* button = g_doc->getElementById(id);
    if (!button) {
        check(cat("ui.", id), false, "button missing");
        return;
    }
    button->addEventListener("click", [handler](kui::Event&) { handler(); });
}

}  // namespace

void tour_ready(kui::Window& window, kui::Document& document) {
    (void)window;
    g_doc = &document;

    run_group("class", check_class_list);
    run_group("style", check_inline_style);
    run_group("computed", check_computed);
    run_group("sheets", check_stylesheets);
    start_animation_checks();  // finishes the verdict from its timer

    on_click("btn-cls-toggle", on_cls_toggle);
    on_click("btn-cls-add", on_cls_add);
    on_click("btn-cls-remove", on_cls_remove);
    on_click("btn-cls-reset", on_cls_reset);
    on_click("btn-st-set", on_st_set);
    on_click("btn-st-text", on_st_text);
    on_click("btn-st-remove", on_st_remove);
    on_click("btn-st-list", on_st_list);
    on_click("btn-cs-read", on_cs_read);
    on_click("btn-cs-wide", on_cs_wide);
    on_click("btn-sheet-add", on_sheet_add);
    on_click("btn-sheet-clear", on_sheet_clear);
    on_click("btn-sheet-profile", on_sheet_profile);
    on_click("btn-anim-toggle", on_anim_toggle);
    on_click("btn-trans-go", on_trans_go);
    on_click("btn-anim-read", on_anim_read);
}
// ---- end of examples/api_tours/style_class/host.cpp ----

int main() {
    try {
        if (!kui::Platform::init()) return 3;
        kui::WindowConfig config;
        config.title = "KUI API \xe2\x80\x94 style & class";
        config.width = 1100;
        config.height = 760;
        auto window = kui::Window::create(config);
        if (!window) return 4;
        kui::Document* document = window->document();
        auto script = kui::ScriptEngine::create();
        if (script) {
            script->setErrorHandler([](const std::string& error, const std::string& source, int line) {
                std::fprintf(stderr, "[Lua] %s:%d: %s\n", source.c_str(), line, error.c_str());
            });
            script->bindDocument(document);
            window->setScriptEngine(script.get());
        }
        tour_script = script.get();
        document->loadHTML(k_tour_page);
        if (script) script->executeScripts();
        // Test hook shared with the C / Go / Rust runners: KUI_EXAMPLE_DEVTOOLS_PORT=<port> starts
        // DevTools so scripts/verify_example_ports.py can click and read the DOM.
        const std::string port = tour_env("KUI_EXAMPLE_DEVTOOLS_PORT");
        if (!port.empty()) window->startDevTools(static_cast<kui::u16>(std::atoi(port.c_str())));
        tour_ready(*window, *document);
        const int code = kui::Platform::run();
        tour_script = nullptr;
        return code;
    } catch (const std::exception& error) {
        std::fprintf(stderr, "[kui_api_style_class] %s\n", error.what());
        return 9;
    }
}
